using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
public partial class NewGameFrontEnd
{
 bool AuthorityHead=>FlowCase is "authority-head" or "authority-created";
 bool AuthorityCreated=>FlowCase=="authority-created";
 bool AuthorityLoss=>FlowCase=="authority-service-loss";
 async Task BeginAuthorityEntry(){await Capture("menu");if(AuthorityCreated){Press("manage");await Frame();await Frame();manager!.ExerciseAuthorityHead("site:kofu");await Capture("registered-officer");PressText(manager,"スタート画面へ");await Frame();}Press("new");Press("next");selectionMode.Select(AuthorityCreated?1:0);selectionMode.EmitSignal(OptionButton.SignalName.ItemSelected,selectionMode.Selected);if(AuthorityCreated)registeredRows.Select(0);Press("next");await Frame();if(AuthorityCreated){incorporate.ButtonPressed=true;incorporate.EmitSignal(BaseButton.SignalName.Toggled,true);}await Capture("placement");Press("next");await Capture("world-review");Press("confirm");await Frame();string id=AuthorityCreated?chosen.Single().Id:"person:shingen";int site=Array.FindIndex(NationalRoutes.Sites,n=>n.Id.Value=="site:kofu");jumpChoice.Select(site);jumpChoice.EmitSignal(OptionButton.SignalName.ItemSelected,site);await Frame();map!.PressSite("site:kofu");PickRow(id);Press("begin");await Frame();await Frame();Check(game!.Session.PlayerControl.Value==id,"actual map/list chooses historical or created head");File.WriteAllText(Path.Combine(TestOutput,"campaign-instance.txt"),game.Profile.Instance);await BeginAuthorityContinuation();}
 async Task AuthorityStep(int n){await Frame();var s=game!.Session;
  if(n==0){Check(game.OffersMilitary(NewMilitaryAction.Request),"same selected person can explicitly start military");game.ChooseMilitary(NewMilitaryAction.Request);var w=s.DiagnosticSnapshot();Check(w.NewMilitary!.Authority!=null&&w.NewMilitary.Requests.First().Input.AuthorityPolicy==NewGameMilitary.AuthorityContract,"actual UI opts new request into source-backed authority");Check(w.NewMilitary!.Authority!.Grants.Length==0,"request grants no command");}
  if(n==1){string before=game.AuthorityText;game.Advance(s.Seconds+1);var w=s.DiagnosticSnapshot();Check(w.NewMilitary!.Authority!.Proofs.Length==1&&!game.OffersMilitary(NewMilitaryAction.Accept),"issuer's real offer is not yet the person's opened notice");Check(game.AuthorityText==before,"unreceived source offer does not change visible authority");}
  if(n==2){game.Advance(s.Seconds+1);OpenAllServiceLetters();Check(game.OffersMilitary(NewMilitaryAction.Accept),"actual opened conditions enable answer");if(AuthorityLoss){game.Press("service-release");game.Advance(s.Seconds+1);Check(!NewGameService.BoundAt(s.DiagnosticSnapshot(),s.DiagnosticSnapshot().NewMilitary!.Terms.Principal,s.Seconds,s.Revision),"service actually ends before pending answer reaches issuer");}}
  if(n==3){game.ChooseMilitary(NewMilitaryAction.Accept);Check(s.DiagnosticSnapshot().NewMilitary!.Authority!.Grants.Length==0,"own answer never creates command");}
  if(n==4){string before=game.AuthorityText;long at=s.DiagnosticSnapshot().NewMilitary!.Requests.Last(q=>q.Input.Action==NewMilitaryAction.Accept).At;game.Advance(at+1);var w=s.DiagnosticSnapshot();Check(w.NewMilitary!.Events.Any(e=>e.Effect==(AuthorityLoss?MilitaryEffect.Refused:MilitaryEffect.Permission)),"actual issuer checks current personal service and authority");Check(!game.OffersMilitary(NewMilitaryAction.Pickup)&&game.AuthorityText==before,"unreceived result does not leak into pickup or authority text");}
  if(n==5){long at=s.DiagnosticSnapshot().NewMilitary!.Requests.Last(q=>q.Input.Action==NewMilitaryAction.Accept).At;game.Advance(at+2);OpenAllServiceLetters();var w=s.DiagnosticSnapshot();if(AuthorityLoss){Check(w.NewMilitary!.Authority!.Grants.Length==0&&!game.OffersMilitary(NewMilitaryAction.Pickup)&&game.AuthorityText.Contains("不承諾"),"physical refusal is known and no unit command exists");}else{Check(game.OffersMilitary(NewMilitaryAction.Pickup)&&w.NewMilitary!.Authority!.Grants.Length==0&&game.AuthorityText.Contains("現地引受前"),"known permission is not yet actual command pickup");}}
  if(n==6){if(AuthorityLoss){game.Advance(s.Seconds+3);game.Press("rotate");}else{game.ChooseMilitary(NewMilitaryAction.Pickup);game.ChooseMilitary(NewMilitaryAction.Load);game.ChooseMilitary(NewMilitaryAction.Deploy);await Frame();await Frame();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());game.ExerciseMilitaryLine(new(a.X+20000,a.Y-12000),new(a.X+20000,a.Y+12000));game.Advance(s.Seconds+2);var w=s.DiagnosticSnapshot();var g=w.NewMilitary!.Authority!.Grants.Single();Check(g.Owner==w.NewMilitary.Terms.Owner&&g.Mandate.Agent==s.PlayerControl&&g.Mandate.Units.SequenceEqual(NewGameMilitary.UnitIds),"source-backed grant is bounded to real owner agent case and three units");Check(!g.Mandate.Actions.Contains(RegionalAction.Engage)&&NewGameMilitary.Moving(w),"placement authority moves actual units without historical combat authority");Check(game.MilitaryModelsFit(),"all actual granted unit models fit the camera");if(AuthorityHead){Check(!w.ServiceBonds.Any(b=>b.Subject==s.PlayerControl&&b.Target==s.PlayerControl),"no fictional self-service relation");Check(!w.Couriers!.Missions.Any(c=>NewGameMilitary.HandlesInternalAuthorityMessage(w,w.Messaging.Attempts.Single(a=>a.Id==c.Attempt).MessageId)),"own decisions never create a courier to absent self");}}}
  if(n==7){if(AuthorityLoss){game.Advance(s.Seconds+3);Check(s.DiagnosticSnapshot().NewMilitary!.Authority!.Grants.Length==0,"refused military never later becomes command");}else{game.ChooseMilitary(NewMilitaryAction.Recall);game.Advance(ArmyEnd()+1);game.ChooseMilitary(NewMilitaryAction.Enter);game.ChooseMilitary(NewMilitaryAction.Unload);game.ChooseMilitary(NewMilitaryAction.Report);game.Advance(s.Seconds+1);game.ChooseMilitary(NewMilitaryAction.Return);game.Advance(s.Seconds+2);OpenAllServiceLetters();var w=s.DiagnosticSnapshot();Check(w.NewMilitary!.Authority!.Grants.Single().UntilRevision!=null&&game.AuthorityText.Contains("指揮返還を確認"),"actual stock return and report close only this loan command");Check(w.Units.All(u=>u.Organization==w.NewMilitary.Terms.Owner)&&w.ResourceLots.Where(l=>l.Kind=="rice").All(l=>l.Owner==w.NewMilitary.Terms.Owner),"return never transfers house property to person");}}
  game.Refresh();Check(game.RecognitionModelsMatch(),"actual authority world and recognized3D agree at"+n);game.Press("save");await WaitSave();
 }
 async Task BeginAuthorityContinuation(){for(int n=0;n<8;n++){await AuthorityStep(n);game!.SaveCheckpoint("authority"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreAuthority(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,row=>row.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<8;n++){game!.LoadCheckpoint("authority"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"same source authority knowledge roster and3D after restore"+n);await Capture("restored-s"+n,true);for(int k=n+1;k<8;k++)await AuthorityStep(k);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same military authority future from"+n);await Capture("continued-s"+n,true);GD.Print("MILITARY_AUTHORITY_RESTORED "+n);}}
 async Task RunAuthorityChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreAuthority();else if(AuthorityHead)await BeginAuthorityEntry();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--military-authority-film")){game!.LoadCheckpoint("authority6");game.Press("auto");string dir=Path.Combine(TestOutput,"film",TestKey??"normal");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"authority-"+n.ToString("D3")+".png"));}game.Press("pause");File.WriteAllText(Path.Combine(TestOutput,"film-manifest.json"),System.Text.Json.JsonSerializer.Serialize(new{Directory=Path.GetRelativePath(TestOutput,dir),Frames=180,Checkpoint=6,Action="own-head-scope-actual-formation-march"}));}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("MILITARY_AUTHORITY_PASSED "+FlowCase);}
}
